CREATE DATABASE IF NOT EXISTS hms CHARACTER SET utf8mb4;
USE hms;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,phone VARCHAR(20),password VARCHAR(255) NOT NULL,role ENUM('admin','receptionist','nurse','doctor','lab','pharmacist','cashier','records') NOT NULL,active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE password_resets(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,otp_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,attempts TINYINT DEFAULT 0,used TINYINT DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE patients(id INT AUTO_INCREMENT PRIMARY KEY,patient_no VARCHAR(20) UNIQUE,first_name VARCHAR(60) NOT NULL,last_name VARCHAR(60) NOT NULL,gender ENUM('Male','Female','Other') NOT NULL,dob DATE NOT NULL,id_number VARCHAR(20),phone VARCHAR(20),address VARCHAR(150),next_of_kin VARCHAR(100),nok_phone VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE visits(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,status ENUM('registered','triage','consultation','lab','pharmacy','billing','done') DEFAULT 'registered',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE invoices(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,visit_id INT NULL,total DECIMAL(10,2) NOT NULL,paid DECIMAL(10,2) DEFAULT 0,status ENUM('unpaid','partial','paid') DEFAULT 'unpaid',created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE invoice_items(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,description VARCHAR(150) NOT NULL,amount DECIMAL(10,2) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,method ENUM('cash','mpesa','bank') NOT NULL,amount DECIMAL(10,2) NOT NULL,mpesa_ref VARCHAR(20) UNIQUE NULL,bank_name VARCHAR(60) NULL,bank_ref VARCHAR(40) NULL,received_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(bank_name,bank_ref),FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(200),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
